import org.gradle.api.Project
import org.gradle.api.Task
import org.gradle.api.tasks.PathSensitivity
import org.gradle.api.tasks.TaskProvider
import java.util.Base64

/**
 * Registers a task that base64-embeds binary test assets into a generated Kotlin
 * object, decoded at runtime. Resource access differs per platform (JVM classpath /
 * iOS bundle / browser HTTP / Android assets), so instead of per-platform IO the
 * committed files become a commonTest source available identically on every target.
 *
 * Wire the returned provider into the source set:
 * `sourceSets.named("commonTest") { kotlin.srcDir(task) }`.
 */
fun Project.registerEmbeddedTestResources(
    taskName: String,
    inputDir: String,
    fileExtension: String,
    packageName: String,
    objectName: String,
): TaskProvider<Task> {
    val input = layout.projectDirectory.dir(inputDir)
    val genDir = layout.buildDirectory.dir("generated/$taskName/kotlin")
    val projectPath = path
    return tasks.register(taskName) {
        val inDir = input.asFile
        val outRoot = genDir.get().asFile
        inputs.dir(input).withPropertyName("assets")
            .withPathSensitivity(PathSensitivity.RELATIVE)
        outputs.dir(genDir).withPropertyName("out")
        doLast {
            val files = (inDir.listFiles { f -> f.isFile && f.name.endsWith(fileExtension) }
                ?: emptyArray()).sortedBy { it.name }
            val pkgDir = outRoot.resolve(packageName.replace('.', '/'))
            pkgDir.mkdirs()
            val sb = StringBuilder()
            sb.appendLine("package $packageName")
            sb.appendLine()
            sb.appendLine("import kotlin.io.encoding.Base64")
            sb.appendLine("import kotlin.io.encoding.ExperimentalEncodingApi")
            sb.appendLine()
            sb.appendLine("// Generated by $projectPath:$taskName from $inputDir. Do not edit.")
            sb.appendLine("@OptIn(ExperimentalEncodingApi::class)")
            sb.appendLine("internal object $objectName {")
            // JVM caps a single string constant at 64 KB of UTF-8; base64 is ASCII so
            // chunk well under that and concatenate before decoding.
            sb.appendLine("    private fun d(vararg c: String): ByteArray = Base64.decode(c.joinToString(\"\"))")
            for (f in files) {
                val ident = f.nameWithoutExtension.replace(Regex("[^A-Za-z0-9]"), "_")
                val b64 = Base64.getEncoder().encodeToString(f.readBytes())
                val chunks = b64.chunked(32000)
                sb.appendLine("    val $ident: ByteArray by lazy {")
                sb.appendLine("        d(")
                chunks.forEachIndexed { i, c ->
                    sb.appendLine("            \"$c\"" + if (i < chunks.lastIndex) "," else "")
                }
                sb.appendLine("        )")
                sb.appendLine("    }")
            }
            sb.appendLine("}")
            pkgDir.resolve("$objectName.kt").writeText(sb.toString())
        }
    }
}
